if(!lockerSource.includes('Casier profs'))lockerSource=lockerSource.replace("    <button className={page==='Stock'", "    {activeAdmin&&<button className={page==='Casier'?'selected':''} onClick={()=>navigate('Casier')}><FolderOpen size={19}/> Casier profs</button>}\n    <button className={page==='Stock'");
