const lockerV2={"lib/teacher-locker.ts":"import {db} from './data';\nexport const lockerSchema=[\n `CREATE TABLE IF NOT EXISTS teacher_locker_folders(id TEXT PRIMARY KEY,name TEXT NOT NULL COLLATE NOCASE UNIQUE,created_at TEXT NOT NULL)`,\n `CREATE TABLE IF NOT EXISTS teacher_locker_files(id TEXT PRIMARY KEY,folder_id TEXT REFERENCES teacher_locker_folders(id),name TEXT NOT NULL,storage_key TEXT NOT NULL UNIQUE,mime TEXT NOT NULL,size INTEGER NOT NULL CHECK(size>0 AND size<=20971520),archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)),created_at TEXT NOT NULL)`,\n `CREATE INDEX IF NOT EXISTS teacher_locker_file_folder ON teacher_locker_files(folder_id,archived)`,\n `CREATE TRIGGER IF NOT EXISTS teacher_locker_quota BEFORE INSERT ON teacher_locker_files WHEN (SELECT COUNT(*) FROM teacher_locker_files)>=1000 OR (SELECT COALESCE(SUM(size),0) FROM teacher_locker_files)+NEW.size>2147483648 BEGIN SELECT RAISE(ABORT,'teacher_locker_quota'); END`\n];\nlet ready:Promise<unknown>|undefined;\nexport async function ensureLocker(){if(!ready)ready=(async()=>{await db().batch(lockerSchema.map(sql=>db().prepare(sql)));const columns=(await db().prepare('PRAGMA table_info(teacher_locker_folders)').all<{name:string}>()).results;if(!columns.some(c=>c.name==='parent_id')){try{await db().prepare('ALTER TABLE teacher_locker_folders ADD COLUMN parent_id TEXT REFERENCES teacher_locker_folders(id)').run()}catch(e){const current=(await db().prepare('PRAGMA table_info(teacher_locker_folders)').all<{name:string}>()).results;if(!current.some(c=>c.name==='parent_id'))throw e;}}})().catch(e=>{ready=undefined;throw e});await ready;}\nexport const fileTypes:Record<string,string>={pdf:'application/pdf',doc:'application/msword',docx:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',ppt:'application/vnd.ms-powerpoint',pptx:'application/vnd.openxmlformats-officedocument.presentationml.presentation',xls:'application/vnd.ms-excel',xlsx:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',odt:'application/vnd.oasis.opendocument.text',odp:'application/vnd.oasis.opendocument.presentation',ods:'application/vnd.oasis.opendocument.spreadsheet',txt:'text/plain',png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',webp:'image/webp'};\nexport function validLockerHeader(extension:string,b:Uint8Array){const ascii=new TextDecoder('latin1').decode(b);if(extension==='pdf')return ascii.startsWith('%PDF-');if(['docx','pptx','xlsx','odt','odp','ods'].includes(extension))return b[0]===80&&b[1]===75;if(['doc','ppt','xls'].includes(extension))return b[0]===208&&b[1]===207&&b[2]===17&&b[3]===224;if(extension==='png')return b[0]===137&&ascii.slice(1,4)==='PNG';if(['jpg','jpeg'].includes(extension))return b[0]===255&&b[1]===216;if(extension==='webp')return ascii.startsWith('RIFF')&&ascii.slice(8,12)==='WEBP';return extension==='txt'&&!b.includes(0);}\n","app/api/teacher-locker/route.ts":"import {isAdmin} from '@/lib/auth';\nimport {db,bucket,jsonError,safeName} from '@/lib/data';\nimport {ensureLocker,fileTypes,validLockerHeader} from '@/lib/teacher-locker';\nexport const dynamic='force-dynamic';\nexport async function GET(request:Request){\n if(!await isAdmin())return jsonError('Accès réservé aux administrateurs.',403);\n await ensureLocker();const url=new URL(request.url),id=url.searchParams.get('id');\n if(id){const row=await db().prepare('SELECT name,storage_key,mime FROM teacher_locker_files WHERE id=? AND archived=0').bind(id).first<{name:string;storage_key:string;mime:string}>();if(!row)return jsonError('Cours indisponible.',404);const object=await bucket().get(row.storage_key);if(!object)return jsonError('Fichier indisponible.',404);const filename=encodeURIComponent(row.name).replace(/[!'()*]/g,c=>'%'+c.charCodeAt(0).toString(16));return new Response(object.body,{headers:{'Content-Type':row.mime,'Content-Disposition':`attachment; filename=\"cours\"; filename*=UTF-8''${filename}`,'Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff'}});}\n const folders=(await db().prepare('SELECT id,name,parent_id FROM teacher_locker_folders ORDER BY name COLLATE NOCASE').all()).results;\n const files=(await db().prepare('SELECT id,folder_id,name,mime,size,archived,created_at FROM teacher_locker_files ORDER BY created_at DESC').all()).results;\n return Response.json({folders,files},{headers:{'Cache-Control':'private, no-store'}});\n}\nexport async function POST(request:Request){\n if(!await isAdmin())return jsonError('Accès réservé aux administrateurs.',403);\n const origin=request.headers.get('origin');if(origin&&origin!==new URL(request.url).origin)return jsonError('Origine refusée.',403);\n await ensureLocker();\n if(request.headers.get('content-type')?.includes('multipart/form-data')){\n  if(Number(request.headers.get('content-length')||0)>21*1024*1024)return jsonError('20 Mo maximum par cours.',413);\n  let form:FormData;try{form=await request.formData()}catch{return jsonError('Envoi invalide.')}\n  const file=form.get('file'),folder=safeName(form.get('folderId'),80)||null;\n  if(!(file instanceof File)||file.size<1||file.size>20*1024*1024)return jsonError('Choisis un fichier de 20 Mo maximum.',413);\n  const name=file.name.replace(/[\\x00-\\x1f/\\\\]/g,'_').slice(0,180),extension=name.split('.').pop()?.toLowerCase()||'',mime=fileTypes[extension];\n  if(!mime||!validLockerHeader(extension,new Uint8Array(await file.slice(0,256).arrayBuffer())))return jsonError('Format non accepté ou fichier invalide.');\n  if(folder&&!await db().prepare('SELECT id FROM teacher_locker_folders WHERE id=?').bind(folder).first())return jsonError('Dossier inconnu.',404);\n  const id=crypto.randomUUID(),key='teacher-locker/'+id;\n  try{await bucket().put(key,file.stream(),{httpMetadata:{contentType:mime}});await db().prepare('INSERT INTO teacher_locker_files(id,folder_id,name,storage_key,mime,size,created_at) VALUES (?,?,?,?,?,?,?)').bind(id,folder,name,key,mime,file.size,new Date().toISOString()).run();return Response.json({ok:true,id});}catch(e){await bucket().delete(key);return jsonError(String(e).includes('teacher_locker_quota')?'Le casier a atteint sa limite de 1 000 fichiers ou 2 Go.':'Enregistrement impossible.',String(e).includes('teacher_locker_quota')?413:500);}\n }\n let b:Record<string,unknown>;try{b=await request.json()}catch{return jsonError('Données invalides.')}\n const action=safeName(b.action,30),id=safeName(b.id,80),name=safeName(b.name,180);\n if(action==='folder'){if(!name)return jsonError('Nom du dossier requis.');const parent=safeName(b.parentId,80)||null;if(parent&&!await db().prepare('SELECT id FROM teacher_locker_folders WHERE id=?').bind(parent).first())return jsonError('Dossier parent introuvable.',404);try{const folderId=crypto.randomUUID();await db().prepare('INSERT INTO teacher_locker_folders(id,name,parent_id,created_at) VALUES (?,?,?,?)').bind(folderId,name,parent,new Date().toISOString()).run();return Response.json({id:folderId});}catch{return jsonError('Ce nom est déjà utilisé dans le casier. Choisis un autre nom.',409);}}\n if(action==='deleteFolder'){\n  if(!await db().prepare('SELECT id FROM teacher_locker_folders WHERE id=?').bind(id).first())return jsonError('Dossier introuvable.',404);\n  const tree='WITH RECURSIVE tree(id) AS (SELECT id FROM teacher_locker_folders WHERE id=? UNION SELECT f.id FROM teacher_locker_folders f JOIN tree t ON f.parent_id=t.id) ';\n  await db().batch([\n   db().prepare(tree+'UPDATE teacher_locker_files SET archived=1,folder_id=NULL WHERE folder_id IN (SELECT id FROM tree)').bind(id),\n   db().prepare(tree+'DELETE FROM teacher_locker_folders WHERE id IN (SELECT id FROM tree)').bind(id)\n  ]);return Response.json({ok:true});\n }\n if(['archive','restore'].includes(action)){const result=await db().prepare('UPDATE teacher_locker_files SET archived=? WHERE id=?').bind(action==='archive'?1:0,id).run();return result.meta.changes?Response.json({ok:true}):jsonError('Cours inconnu.',404);}\n if(action==='move'){const folder=safeName(b.folderId,80)||null;if(folder&&!await db().prepare('SELECT id FROM teacher_locker_folders WHERE id=?').bind(folder).first())return jsonError('Dossier inconnu.',404);const result=await db().prepare('UPDATE teacher_locker_files SET folder_id=? WHERE id=? AND archived=0').bind(folder,id).run();return result.meta.changes?Response.json({ok:true}):jsonError('Cours inconnu.',404);}\n return jsonError('Action inconnue.');\n}\n","app/teacher-locker.tsx":"'use client';\nimport {useCallback,useEffect,useRef,useState} from 'react';\nimport {FolderOpen,UploadCloud,FileText,Download,Trash2,RefreshCw} from 'lucide-react';\nimport {Dialog,DialogContent,DialogHeader,DialogTitle} from '@/components/ui/dialog';\nimport {toast} from 'sonner';\nimport './teacher-locker.css';\ntype Folder={id:string;name:string;parent_id:string|null};type Course={id:string;folder_id:string|null;name:string;size:number;archived:number;created_at:string};\nfunction auth():Record<string,string>{const token=sessionStorage.getItem('atelier_admin_token');return token?{Authorization:`Bearer ${token}`}:{}}\nexport default function TeacherLocker(){\n const [data,setData]=useState<{folders:Folder[];files:Course[]}|null>(null),[folder,setFolder]=useState(''),[query,setQuery]=useState(''),[trash,setTrash]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState(''),[newFolder,setNewFolder]=useState('');const input=useRef<HTMLInputElement>(null);\n const [parent,setParent]=useState(''),[preview,setPreview]=useState<{name:string;url?:string;kind?:string;text?:string;error?:string}|null>(null);const previewAbort=useRef<AbortController|null>(null);\n useEffect(()=>()=>{previewAbort.current?.abort()},[]);\n useEffect(()=>()=>{if(preview?.url)URL.revokeObjectURL(preview.url)},[preview?.url]);\n function closePreview(){previewAbort.current?.abort();setPreview(null)}\n async function view(course:Course){previewAbort.current?.abort();const controller=new AbortController();previewAbort.current=controller;const ext=course.name.split('.').pop()?.toLowerCase()||'';setPreview({name:course.name});if(!['pdf','png','jpg','jpeg','webp','txt'].includes(ext)){setPreview({name:course.name,error:'Pour lire ce format dans le casier, dépose également une version PDF. Le fichier original reste disponible au téléchargement.'});return}try{const r=await fetch('/api/teacher-locker?id='+encodeURIComponent(course.id),{headers:auth(),cache:'no-store',signal:controller.signal});if(!r.ok)throw Error('Aperçu indisponible.');const blob=await r.blob();if(controller.signal.aborted)return;if(ext==='txt'){const text=await blob.text();if(!controller.signal.aborted)setPreview({name:course.name,kind:'text',text})}else{const mime=ext==='pdf'?'application/pdf':ext==='jpg'||ext==='jpeg'?'image/jpeg':'image/'+ext;const url=URL.createObjectURL(new Blob([blob],{type:mime}));setPreview({name:course.name,kind:ext==='pdf'?'pdf':'image',url})}}catch(e){if(!controller.signal.aborted)setPreview({name:course.name,error:e instanceof Error?e.message:'Aperçu indisponible.'})}}\n\n const refresh=useCallback(async()=>{const r=await fetch('/api/teacher-locker',{headers:auth(),cache:'no-store'}),v=await r.json();if(!r.ok)throw Error(v.error||'Casier indisponible.');setData(v);setError('');},[]);\n useEffect(()=>{refresh().catch(e=>setError(e.message))},[refresh]);\n async function send(body:FormData|Record<string,unknown>){setBusy(true);try{const form=body instanceof FormData,r=await fetch('/api/teacher-locker',{method:'POST',headers:{...auth(),...(form?{}:{'Content-Type':'application/json'})},body:form?body:JSON.stringify(body)}),v=await r.json();if(!r.ok)throw Error(v.error||'Enregistrement impossible.');await refresh();return v;}catch(e){toast.error(e instanceof Error?e.message:'Erreur');return null;}finally{setBusy(false)}}\n async function download(course:Course){setBusy(true);try{const r=await fetch('/api/teacher-locker?id='+encodeURIComponent(course.id),{headers:auth(),cache:'no-store'});if(!r.ok)throw Error('Téléchargement indisponible.');const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download=course.name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}catch(e){toast.error(e instanceof Error?e.message:'Erreur')}finally{setBusy(false)}}\n function folderPath(id:string):string{const names:string[]=[],seen=new Set<string>();let current=data?.folders.find(f=>f.id===id);while(current&&!seen.has(current.id)){seen.add(current.id);names.unshift(current.name);current=data?.folders.find(f=>f.id===current?.parent_id)}return names.join(' / ')}\n const orderedFolders:Folder[]=[];function walk(parentId:string|null){for(const f of data?.folders.filter(f=>(f.parent_id||null)===parentId)||[]){orderedFolders.push(f);walk(f.id)}}walk(null);\n const files=data?.files.filter(f=>!!f.archived===trash&&(trash||!folder||f.folder_id===folder)&&f.name.toLocaleLowerCase('fr').includes(query.toLocaleLowerCase('fr')))||[];\n return <><div className=\"heading-row\"><div><div className=\"eyebrow\"><span/> ESPACE COMMUN DES PROFESSEURS</div><h1>Casier profs<span className=\"title-dot\">.</span></h1><p>Vos cours et supports, accessibles uniquement aux administrateurs.</p></div><button className=\"secondary\" onClick={()=>refresh().catch(e=>setError(e.message))}><RefreshCw size={16}/> Actualiser</button></div>\n {error&&<p className=\"error\" role=\"alert\">{error}</p>}\n {!data&&!error?<p className=\"loading\">Chargement du casier…</p>:data&&<div className=\"locker-layout\"><aside className=\"locker-folders\"><h2><FolderOpen size={18}/> Dossiers</h2><button className={!folder&&!trash?'active':''} onClick={()=>{setFolder('');setTrash(false)}}>Tous les cours</button>{orderedFolders.map(f=><button key={f.id} className={folder===f.id&&!trash?'active':''} onClick={()=>{setFolder(f.id);setTrash(false)}}><FolderOpen size={16}/>{folderPath(f.id)}</button>)}<button className={trash?'active':''} onClick={()=>setTrash(true)}><Trash2 size={16}/> Corbeille</button><form className=\"form-stack\" onSubmit={async e=>{e.preventDefault();const v=await send({action:'folder',name:newFolder,parentId:parent});if(v){setNewFolder('');setFolder(v.id);setTrash(false)}}}><label>Dans le dossier<select value={parent} onChange={e=>setParent(e.target.value)}><option value=\"\">Racine du casier</option>{orderedFolders.map(f=><option key={f.id} value={f.id}>{folderPath(f.id)}</option>)}</select></label><label>Nouveau dossier<input required maxLength={180} value={newFolder} onChange={e=>setNewFolder(e.target.value)} placeholder=\"Ex. Première — Tournage\"/></label><button className=\"secondary\" disabled={busy}>Créer le dossier</button></form></aside>\n <section className=\"locker-files\">{!trash&&<div className=\"locker-location\"><strong>{folder?folderPath(folder):'Tous les cours'}</strong>{folder&&<><button className=\"secondary\" onClick={()=>setParent(folder)}>Créer un sous-dossier ici</button><button className=\"danger-soft\" disabled={busy} onClick={async()=>{if(window.confirm('Supprimer ce dossier et tous ses sous-dossiers ? Les cours seront placés dans la corbeille et pourront être restaurés sans dossier.')){if(await send({action:'deleteFolder',id:folder})){setFolder('');setParent('')}}}}>Supprimer ce dossier</button></>}</div>}<div className=\"locker-tools\"><input aria-label=\"Rechercher un cours\" placeholder=\"Rechercher un cours…\" value={query} onChange={e=>setQuery(e.target.value)}/>{!trash&&<button className=\"primary\" disabled={busy} onClick={()=>input.current?.click()}><UploadCloud size={18}/> Déposer un cours</button>}<input hidden ref={input} type=\"file\" accept=\".pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.odt,.odp,.ods,.txt,.png,.jpg,.jpeg,.webp\" onChange={async e=>{const f=e.target.files?.[0];e.target.value='';if(!f)return;if(f.size>20*1024*1024){toast.error('20 Mo maximum par cours.');return;}const form=new FormData();form.append('file',f);form.append('folderId',folder);if(await send(form))toast.success('Cours ajouté au casier.');}}/></div><p className=\"locker-help\">{trash?'Les cours retirés peuvent être restaurés.':`Dépôt ${folder?'dans « '+data.folders.find(f=>f.id===folder)?.name+' »':'sans dossier'} · PDF, Word, PowerPoint, Excel, LibreOffice et images · 20 Mo maximum.`}</p>\n {files.length?<div className=\"locker-list\">{files.map(f=><article className=\"locker-row\" key={f.id}><FileText size={23}/><div><strong>{f.name}</strong><small>{(f.size/1024/1024).toFixed(2)} Mo · {f.folder_id?folderPath(f.folder_id):'Sans dossier'} · {new Date(f.created_at).toLocaleDateString('fr-FR')}</small></div>{trash?<button className=\"secondary\" disabled={busy} onClick={()=>send({action:'restore',id:f.id})}>Restaurer</button>:<><select aria-label={'Dossier de '+f.name} disabled={busy} value={f.folder_id||''} onChange={e=>send({action:'move',id:f.id,folderId:e.target.value})}><option value=\"\">Sans dossier</option>{data.folders.map(d=><option key={d.id} value={d.id}>{folderPath(d.id)}</option>)}</select><button className=\"secondary\" disabled={busy} onClick={()=>view(f)}>Aperçu</button><button className=\"secondary\" disabled={busy} onClick={()=>download(f)} aria-label={'Télécharger '+f.name}><Download size={17}/></button><button className=\"danger-soft\" disabled={busy} onClick={()=>{if(window.confirm('Déplacer « '+f.name+' » dans la corbeille commune ?'))send({action:'archive',id:f.id})}} aria-label={'Mettre à la corbeille '+f.name}><Trash2 size={17}/></button></>}</article>)}</div>:<div className=\"empty\">{trash?'La corbeille est vide.':'Aucun cours ici pour le moment.'}</div>}</section></div>}\n <Dialog open={!!preview} onOpenChange={open=>{if(!open)closePreview()}}><DialogContent className=\"locker-preview\"><DialogHeader><DialogTitle>{preview?.name||'Aperçu du cours'}</DialogTitle></DialogHeader>{preview?.error?<p>{preview.error}</p>:preview?.kind==='pdf'?<><p className=\"locker-help\">Si le lecteur PDF de ton appareil ne s’affiche pas, utilise le bouton de téléchargement du cours.</p><iframe title={preview.name} src={preview.url}/></>:preview?.kind==='image'?<img src={preview.url} alt={preview.name}/>:preview?.kind==='text'?<pre>{preview.text}</pre>:<p role=\"status\">Chargement de l’aperçu…</p>}</DialogContent></Dialog>\n </>;\n}\n","app/teacher-locker.css":".locker-layout{display:grid;grid-template-columns:250px minmax(0,1fr);gap:22px}.locker-folders,.locker-files{background:#192734;border:1px solid #35495d;border-radius:16px;padding:20px;min-width:0}.locker-folders h2{display:flex;gap:9px;align-items:center;font-size:18px;margin:0 0 16px}.locker-folders>button{display:flex;align-items:center;gap:8px;word-break:break-word;width:100%;text-align:left;border:0;background:transparent;color:#adc4d9;padding:12px;border-radius:9px}.locker-folders>button.active{background:#244d72;color:white}.locker-folders .form-stack{border-top:1px solid #35495d;margin-top:20px;padding-top:18px}.locker-tools{display:flex;gap:12px;flex-wrap:wrap}.locker-tools>input:not([hidden]){flex:1;min-width:150px;background:#101b27;color:white;border:1px solid #40566b;border-radius:9px;padding:12px}.locker-help{color:#9eb5ca;font-size:12px;line-height:1.6;margin:14px 0 20px}.locker-list{display:grid;gap:10px}.locker-row{display:flex;gap:11px;align-items:center;padding:13px;border:1px solid #35495d;border-radius:10px;flex-wrap:wrap}.locker-row>svg{color:#7dbbfa}.locker-row>div{flex:1;min-width:130px;overflow-wrap:anywhere}.locker-row strong{font-size:14px;display:block}.locker-row small{display:block;color:#9eb5ca;font-size:11px;margin-top:5px}.locker-row select{background:#172838;color:#d4e6f7;border:1px solid #40566b;border-radius:7px;padding:7px;max-width:170px;font-size:12px}.locker-row .secondary,.locker-row .danger-soft{padding:8px 11px}:root[data-theme=\"light\"] .locker-folders,:root[data-theme=\"light\"] .locker-files{background:#fff;border-color:#cbdbe8}:root[data-theme=\"light\"] .locker-folders>button{color:#37546d}:root[data-theme=\"light\"] .locker-folders>button.active{background:#d0e4f6;color:#103654}:root[data-theme=\"light\"] .locker-help,:root[data-theme=\"light\"] .locker-row small{color:#526b82}:root[data-theme=\"light\"] .locker-row{border-color:#cbdbe8}:root[data-theme=\"light\"] .locker-tools>input:not([hidden]),:root[data-theme=\"light\"] .locker-row select{background:#fff;color:#18344d;border-color:#b4c8d8}@media(max-width:850px){.locker-layout{grid-template-columns:1fr}.locker-folders,.locker-files{padding:15px}.locker-row select{max-width:100%;flex-basis:100%}}\n.locker-location{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:18px}.locker-location strong{flex:1;min-width:150px;overflow-wrap:anywhere}.locker-folders select{display:block;max-width:100%;padding:9px;border-radius:8px;background:#172838;color:#d4e6f7;border:1px solid #40566b}.locker-preview{width:94vw!important;max-width:1100px!important;max-height:92dvh;overflow:auto}.locker-preview iframe{width:100%;height:70dvh;border:0;background:white}.locker-preview img{max-width:100%;max-height:72dvh;object-fit:contain;margin:auto}.locker-preview pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:70dvh;overflow:auto}:root[data-theme=\"light\"] .locker-folders select{background:white;color:#18344d}\n"};
